figure.sourcecode:
aee-statement = agent-credential / policy-pack / config-integrity / config-drift / execution-receipt / execution-epoch / assurance / revocation / agent-registration / serving-party-credential / model-provider
aee-type = &( agent-credential: 1, policy-pack: 2, config-integrity: 3, config-drift: 4, execution-receipt: 5, execution-epoch: 6, assurance: 7, revocation: 8, agent-registration: 9, serving-party-credential: 10, model-provider: 11 )
; A digest is a COSE hash algorithm identifier and the digest value. ; SHA-256 is -16 in the IANA COSE Algorithms registry. digest = [ alg: int, value: bstr ]
validity = { 1 => uint, ; nbf, seconds since the Unix epoch 2 => uint ; exp, seconds since the Unix epoch }
principal = { 1 => principal-kind, ; kind 2 => bstr / tstr, ; id: 32-octet digest for natural persons, ; otherwise an identifier ? 3 => principal-assurance, ; principal_assurance ? 4 => delegation-ref ; delegation_ref } principal-kind = &( natural-person: 1, organization: 2, workload: 3 )
; How strongly the Principal was verified, as a Vector of Trust ; (RFC 8485): the vector (at least its identity proofing ; component) and the trustmark URL of the trust framework ; that defines the values. principal-assurance = { 1 => tstr, ; vot, for example "P2" 2 => tstr, ; vtm, trustmark URL ? 3 => tstr ; verifier: who performed the proofing }
; The Principal's grant of authority to this agent. delegation-ref = { 1 => digest, ; token_digest of the delegation token ? 2 => status-ref ; status of this delegation }

agent-credential = { 1 => 1, ; aee-type 2 => tstr, ; agent_id (see {{ids}}) 3 => COSE_Key, ; agent_key, RFC 9052 Section 7 4 => principal, ; principal 5 => harness, ; harness 6 => model-binding, ; model_binding 7 => validity, ; validity ? 8 => tstr, ; credential_ref: identifier of the ; workload credential (e.g. WIT jti, ; certificate thumbprint) this binds to 9 => tstr, ; logical_agent_id 10 => principal, ; responsible_entity 11 => [ + runtime-identity ], ; runtime_identities 12 => lifecycle-class, ; lifecycle_class 13 => digest, ; registration_digest: digest of the ; Agent Registration Statement payload ? 14 => [ + subagent ], ; subagents ? 15 => [ + tstr ] ; hosts (see {{serving}}) }
runtime-identity = { 1 => tstr, ; identifier 2 => id-scheme, ; scheme 3 => tstr, ; trust_domain 4 => uint, ; valid_from, seconds since Unix epoch 5 => uint ; valid_until } id-scheme = &( wimse: 1, spiffe: 2, did: 3, oidc: 4, cloud-native: 5, other: 6 ) lifecycle-class = &( ephemeral: 1, persistent: 2 )
subagent = { 1 => tstr, ; subagent_ref, unique within the parent 2 => tstr, ; function, as declared ? 3 => COSE_Key, ; subagent_key ? 4 => [ + runtime-identity ] ; runtime_identities }
harness = { 1 => tstr, ; name 2 => tstr, ; version ? 3 => digest ; digest: of the harness binary/image }
model-binding = { 1 => binding-mode, ; mode ? 2 => digest, ; weights_digest (mode 1 only) ? 3 => tstr, ; model_id as named by the provider ? 4 => tstr, ; provider ? 5 => bstr, ; tee_evidence: digest of or reference ; to RATS Evidence (mode 3 only) ? 6 => digest ; provider_statement_digest } binding-mode = &( weights-digest: 1, api: 2, api-tee: 3 )
